// Institutional orders and catalog operations. Demo records remain browser-local.
let bulkOrders=read('bulk-orders',[]),priceHistory=read('price-history',[]),bulkDraft=null,bulkFilter='All',pricingSelection=new Set(),pricingCategory='',pricingQuery='',pricingPreview=null,catalogWorkbook=null,catalogFilename='',catalogSheet='',catalogMap={},catalogPreview=null;
const bulkStages=['Submitted','Quoted','Delivered','Completed'];
const stamp=()=>new Date().toISOString();
const dateLabel=value=>new Date(value).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'});
function persistRecords(changes){const previous={};for(const k of Object.keys(changes))previous[k]=localStorage.getItem('circuit-demo-'+k);try{for(const [k,v] of Object.entries(changes))localStorage.setItem('circuit-demo-'+k,JSON.stringify(v))}catch{for(const [k,v] of Object.entries(previous)){try{if(v===null)localStorage.removeItem('circuit-demo-'+k);else localStorage.setItem('circuit-demo-'+k,v)}catch{}}throw Error('Browser storage is full. Changes were not saved.')}}
function recordPriceChange(p,next,reason,batchId=''){if(Number(p.price)===Number(next))return;priceHistory.unshift({id:crypto.randomUUID(),productId:p.id,name:p.name,category:p.category,before:p.price,after:Number(next),reason,batchId,actor:user?.email||'admin',at:stamp()});}
function commitProductChanges(changes,reason){requireDemoAdmin();const previousProducts=JSON.stringify(products),previousHistory=JSON.stringify(priceHistory),batch=crypto.randomUUID();try{for(const c of changes){const p=product(c.id);if(!p)throw Error('A selected product no longer exists.');if(c.price!==undefined&&(!Number.isFinite(c.price)||c.price<0.01||c.price>1000000))throw Error('Prices must be between ₹0.01 and ₹10,00,000.');if(c.stock!==undefined&&(!Number.isInteger(c.stock)||c.stock<0||c.stock>100000))throw Error('Stock must be between 0 and 1,00,000 units.');if(c.price!==undefined)recordPriceChange(p,c.price,reason,batch);Object.assign(p,c);p.old=Math.max(p.old,p.price);p.tag=p.stock?(p.old>p.price?Math.round((1-p.price/p.old)*100)+'% off':'Maker favourite'):'Sold out'}const nextCart=cart.map(i=>({...i,qty:Math.min(i.qty,product(i.id).stock)})).filter(i=>i.qty>0&&product(i.id)?.active!==false);persistRecords({products,'price-history':priceHistory,cart:nextCart});cart=nextCart;updateHeader();syncCardControls();}catch(error){products=JSON.parse(previousProducts);priceHistory=JSON.parse(previousHistory);throw error}}
function opsHeading(eyebrow,title,description,actions=''){return `<div class="import-page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${actions}</div>`}
