function customerBulkPage(){const mine=user?.role==='customer'?bulkOrders.filter(o=>o.owner===user.email):[];return `<div class="wrap bulk-customer">${crumbs('Institutional bulk orders')}${opsHeading('For classrooms, labs and institutions','One spreadsheet. Your whole project.','Send your component list and quantities. Our team will review it and prepare a quotation.')}<div class="bulk-layout"><section class="panel"><div class="section-head"><h3>Request a bulk quotation</h3><span class="file-types">XLSX · XLS · CSV</span></div><form id="bulkrequestform"><div class="form-grid">${field('Full name','name',profile.name,'text',true)}${field('Email address','email',user?.role==='customer'?user.email:'','email',true)}${field('Phone number','phone',profile.phone,'tel',true,'[0-9+ ()-]{10,18}')}<label class="field">Institution type<select name="institutionType" required><option>College</option><option>University</option><option>School</option></select></label><label class="field full">College / university / school name<input name="institution" required maxlength="180" placeholder="e.g. National Institute of Technology"></label><label class="field full">Additional requirements <span class="subtle">(optional)</span><textarea name="notes" maxlength="2000" rows="3" placeholder="Delivery location, required date, specifications…"></textarea></label></div><div class="bulk-upload"><label class="field">Upload your item list<input id="bulkfile" type="file" accept=".xlsx,.xls,.csv" required></label><small>Up to 250 lines · 5 MB · Item and Count columns</small></div><div id="bulkpreview" aria-live="polite"></div><p class="error" id="bulkerror" role="alert"></p><button class="btn" id="bulksubmit" disabled>Submit quotation request</button><p class="subtle">Submitting requests a quote. It does not place or pay for an order.</p></form></section><aside><section class="panel bulk-guide"><div class="eyebrow">Start here</div><h3>Your list, our expertise.</h3><p>Download the template, replace the example items and enter how many units you need.</p><a class="btn btn-outline" href="/samples/power-electronics-bulk-order.xlsx" download>Download sample Excel</a><a class="text-link" href="/samples/power-electronics-bulk-order.csv" download>Download CSV</a><ol><li><b>Prepare your list</b><span>One item per row. Count must be a positive whole number.</span></li><li><b>Add your details</b><span>Provide your contact and institution information.</span></li><li><b>Track your request</b><span>Follow your quotation and delivery status below.</span></li></ol></section><div class="saved-note">Demo requests are stored in this browser. Switch to the admin login here to review them.</div></aside></div><section class="section"><div class="section-head"><h2>Your bulk requests</h2><span>${mine.length} requests</span></div>${user?.role!=='customer'?'<div class="panel"><p>Sign in as a customer to submit a request and track its progress.</p><button class="btn btn-outline" data-action="login">Customer login</button></div>':mine.length?mine.map(o=>bulkOrderCard(o)).join(''):'<div class="import-empty"><h3>Your first request starts here.</h3><p>Submit your spreadsheet to see its quotation status.</p></div>'}</section></div>`}
function normalizeBulkRows(matrix){if(!matrix?.length)throw Error('The file is empty.');const headers=matrix[0].map(v=>String(v??'').toLowerCase().replace(/[^a-z]/g,'')),item=headers.findIndex(h=>['item','product','productname','sku'].includes(h)),count=headers.findIndex(h=>['count','quantity','qty'].includes(h));if(item<0||count<0)throw Error('The first row must contain Item and Count columns.');if(headers.filter(h=>['item','product','productname','sku'].includes(h)).length!==1||headers.filter(h=>['count','quantity','qty'].includes(h)).length!==1)throw Error('Use one Item column and one Count column.');const rows=matrix.slice(1).map((r,i)=>({item:String(r[item]??'').trim(),count:String(r[count]??'').trim(),row:i+2})).filter(r=>r.item||r.count);if(!rows.length||rows.length>250)throw Error('Include between 1 and 250 item rows.');const seen=new Set();return rows.map(r=>{const n=Number(r.count);if(!r.item||r.item.length>180)throw Error(`Row ${r.row}: enter an item name or SKU (up to 180 characters).`);if(!r.count||!Number.isInteger(n)||n<1||n>100000)throw Error(`Row ${r.row}: Count must be a whole number from 1 to 1,00,000.`);const key=r.item.toLowerCase();if(seen.has(key))throw Error(`Row ${r.row}: duplicate item. Combine quantities into one row.`);seen.add(key);return {item:r.item,count:n}})}
async function workbookFromFile(file){if(!file)throw Error('Choose a spreadsheet first.');if(!/\.(xlsx|xls|csv)$/i.test(file.name))throw Error('Choose an XLSX, XLS or CSV file.');if(file.size>5*1024*1024)throw Error('Maximum file size is 5 MB.');if(typeof XLSX==='undefined')throw Error('Excel reader is unavailable. Reload the page.');const buffer=await file.arrayBuffer();return XLSX.read(buffer,{type:'array',sheetRows:252,cellFormula:true})}
function sheetMatrix(wb,name){const sheet=wb.Sheets[name];if(!sheet)throw Error('Choose a worksheet.');const range=sheet['!fullref']||sheet['!ref'];if(range&&XLSX.utils.decode_range(range).e.r>250)throw Error('Maximum 250 data rows per upload.');for(const [key,cell] of Object.entries(sheet))if(!key.startsWith('!')&&cell.f)throw Error('Replace spreadsheet formulas with plain values.');return XLSX.utils.sheet_to_json(sheet,{header:1,defval:'',blankrows:false,raw:true})}
async function loadBulkFile(file){bulkDraft=null;$('#bulksubmit').disabled=true;$('#bulkerror').textContent='';$('#bulkpreview').innerHTML='Reading and validating your list…';const wb=await workbookFromFile(file),name=wb.SheetNames.find(n=>n.toLowerCase()==='items')||wb.SheetNames[0],items=normalizeBulkRows(sheetMatrix(wb,name));bulkDraft={items,filename:file.name};$('#bulkpreview').innerHTML=`<div class="saved-note">${items.length} line items · ${items.reduce((a,i)=>a+i.count,0)} units · Ready to submit</div><div class="table-scroll bulk-preview-table"><table class="data-table"><thead><tr><th>Item</th><th>Count</th></tr></thead><tbody>${items.map(i=>`<tr><td>${esc(i.item)}</td><td>${i.count}</td></tr>`).join('')}</tbody></table></div>`;$('#bulksubmit').disabled=false}
function submitBulkRequest(data){if(user?.role!=='customer')throw Error('Sign in as a customer before submitting.');if(!bulkDraft)throw Error('Upload and validate your item list first.');if(!data.name.trim()||!data.institution.trim()||!['College','University','School'].includes(data.institutionType)||!/^\S+@\S+\.\S+$/.test(data.email)||!/^[0-9+ ()-]{10,18}$/.test(data.phone)||data.phone.replace(/\D/g,'').length<10)throw Error('Provide a valid name, email, phone and institution.');const shipping=validateShipping(data),alternatePhone=validateAlternatePhone(data.alternatePhone);const now=stamp(),o={id:'BQ-'+crypto.randomUUID().slice(0,8).toUpperCase(),owner:user.email,shipping,alternatePhone,name:data.name.trim().slice(0,180),email:data.email.trim().toLowerCase(),phone:data.phone.trim(),institution:data.institution.trim().slice(0,180),institutionType:data.institutionType,notes:data.notes.trim().slice(0,2000),items:bulkDraft.items,filename:bulkDraft.filename,status:'Submitted',quote:null,adminNotes:'',createdAt:now,history:[{status:'Submitted',at:now,note:'Request submitted',actor:user.email}]};persistRecords({'bulk-orders':[o,...bulkOrders]});bulkOrders.unshift(o);bulkDraft=null;return o}
function adminBulkPage(){if(user?.role!=='admin')return admin();const list=bulkOrders.filter(o=>bulkFilter==='All'||o.status===bulkFilter);return importLayout(`${opsHeading('Institutional sales','Bulk orders','Review customer lists, issue quotations and track delivery through completion.')}<div class="metrics bulk-metrics">${bulkStages.map(s=>`<div class="metric"><small>${s}</small><strong>${bulkOrders.filter(o=>o.status===s).length}</strong><span>${s==='Submitted'?'Awaiting review':s==='Quoted'?'Quotation issued':s==='Delivered'?'Awaiting completion':'Closed requests'}</span></div>`).join('')}</div><div class="panel"><div class="section-head"><h3>Quotation requests</h3><select data-ops-filter="bulk" aria-label="Filter bulk requests">${['All',...bulkStages].map(s=>`<option ${bulkFilter===s?'selected':''}>${s}</option>`).join('')}</select></div>${list.length?list.map(o=>bulkOrderCard(o,true)).join(''):'<div class="import-empty"><h3>No requests here yet.</h3><p>Customer Excel requests will appear here after submission.</p><a class="btn btn-outline" href="#/bulk-orders">View customer request page</a></div>'}</div>`,'bulk')}
function bulkDetail(id){const o=bulkOrders.find(o=>o.id===id);if(!o||!user||(user.role!=='admin'&&o.owner!==user.email))throw Error('Request is unavailable for this account.');const isAdmin=user.role==='admin',next=bulkStages[bulkStages.indexOf(o.status)+1];showModal(`<div class="eyebrow">Bulk quotation request</div><h2>${esc(o.id)}</h2><p>${esc(o.institutionType)} · ${esc(o.institution)}</p>${bulkTimeline(o)}<div class="request-contact"><b>${esc(o.name)}</b><span>${esc(o.email)} · ${esc(o.phone)}</span><span>File: ${esc(o.filename)}</span>${o.notes?`<span>Requirements: ${esc(o.notes)}</span>`:''}</div><div class="table-scroll bulk-preview-table"><table class="data-table"><thead><tr><th>Requested item</th><th>Count</th></tr></thead><tbody>${o.items.map(i=>`<tr><td>${esc(i.item)}</td><td>${i.count}</td></tr>`).join('')}</tbody></table></div>${isAdmin?`<form id="bulkmanageform" data-id="${o.id}"><div class="form-grid"><label class="field">Quote total (₹)<input name="quote" type="number" min="0.01" max="1000000000" step="0.01" value="${o.quote??''}" ${next?'required':'readonly'}></label><label class="field">Update status<select name="status"><option>${o.status}</option>${next?`<option>${next}</option>`:''}</select></label><label class="field full">Customer-visible admin notes<textarea name="adminNotes" maxlength="2000" rows="3">${esc(o.adminNotes)}</textarea></label></div><p id="bulkmanageerror" class="error" role="alert"></p><button class="btn">Save request update</button></form>`:`<div class="saved-note">${o.quote===null?'Our team is reviewing your list.':`Quotation total: ${money(o.quote)}`}${o.adminNotes?`<p>${esc(o.adminNotes)}</p>`:''}</div>`}<h3 class="timeline-title">Activity timeline</h3><div class="activity-timeline">${o.history.slice().reverse().map(h=>`<div><b>${esc(h.status)}</b><small>${dateLabel(h.at)}</small><p>${esc(h.note)}</p></div>`).join('')}</div>`);$('#modal').classList.add('operations-modal')}
function updateBulkOrder(id,data){requireDemoAdmin();const o=bulkOrders.find(o=>o.id===id);if(!o)throw Error('Request not found.');const index=bulkStages.indexOf(o.status),target=bulkStages.indexOf(data.status),quote=String(data.quote??'').trim()===''?null:Number(data.quote);if(target<index||target>index+1||target<0)throw Error('Advance one stage at a time.');if((target>0&&quote===null)||(quote!==null&&(!Number.isFinite(quote)||quote<=0||quote>1000000000)))throw Error('Enter a positive quotation total.');if(o.status==='Completed'&&(quote!==o.quote||data.adminNotes!==o.adminNotes))throw Error('Completed requests are closed.');const copy=structuredClone(bulkOrders),updated=copy.find(x=>x.id===id);updated.status=data.status;updated.quote=quote;updated.adminNotes=data.adminNotes.trim().slice(0,2000);if(o.status!==updated.status||o.quote!==quote||o.adminNotes!==updated.adminNotes)updated.history.push({status:updated.status,at:stamp(),actor:user.email,note:`${quote===null?'Review in progress':'Quote '+money(quote)}${updated.adminNotes?' · '+updated.adminNotes:''}`});persistRecords({'bulk-orders':copy});bulkOrders=copy}
function filteredPricingProducts(){return products.filter(p=>(!pricingCategory||p.category===pricingCategory)&&(!pricingQuery||`${p.name} ${p.sku||''}`.toLowerCase().includes(pricingQuery.toLowerCase())))}
function pricingPage(){if(user?.role!=='admin')return admin();const list=filteredPricingProducts();return importLayout(`${opsHeading('Catalog controls','Pricing & inventory','Adjust prices across your catalog or a category. Select individual items for stock actions.', '<a class="btn btn-outline" href="#/admin/price-history">View price history</a>')}<div class="pricing-layout"><section class="panel"><h3>Bulk price adjustment</h3><p>Review every affected price before applying changes.</p><form id="priceadjustform"><label class="field">Apply to<select name="scope"><option value="all">All products</option><option value="category">Current category</option><option value="selected">Selected products (${pricingSelection.size})</option></select></label><div class="form-grid"><label class="field">Adjustment type<select name="type"><option value="percent">Percentage (%)</option><option value="fixed">Fixed amount (₹)</option><option value="outofstock">Mark out of stock</option></select></label><label class="field">Direction<select name="direction"><option value="increase">Increase</option><option value="decrease">Decrease</option></select></label><label class="field">Amount<input name="amount" type="number" min="0.01" max="1000000" step="0.01" placeholder="e.g. 0.5 or 25" required></label><label class="field">Reason<input name="reason" maxlength="180" required placeholder="e.g. Supplier price revision"></label></div><div class="saved-note">0.5 means a 0.5% change. Prices are rounded to two decimals. Compare-at prices are raised only when needed.</div><p id="priceerror" class="error" role="alert"></p><button class="btn">Preview price changes</button></form></section><section class="panel inventory-panel"><div class="section-head"><h3>Product selection</h3><span>${pricingSelection.size} selected</span></div><div class="upload-toolbar"><input id="pricingsearch" value="${esc(pricingQuery)}" placeholder="Search product or SKU" aria-label="Search inventory"><select data-ops-filter="category" aria-label="Filter inventory by category"><option value="">All categories</option>${categories.map(([c])=>`<option ${pricingCategory===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="inventory-actions"><button class="btn btn-outline btn-small" data-ops="stock-zero" ${!pricingSelection.size?'disabled':''}>Mark selected out of stock</button><button class="btn btn-outline btn-small" data-ops="stock-set" ${!pricingSelection.size?'disabled':''}>Set stock quantity</button></div><div class="table-scroll inventory-table"><table class="data-table"><thead><tr><th><input type="checkbox" data-ops-select-all aria-label="Select visible inventory" ${list.length&&list.every(p=>pricingSelection.has(p.id))?'checked':''}></th><th>Product</th><th>Price</th><th>Stock</th><th></th></tr></thead><tbody>${list.map(p=>`<tr><td><input type="checkbox" data-ops-select="${p.id}" aria-label="Select ${esc(p.name)}" ${pricingSelection.has(p.id)?'checked':''}></td><td><div class="table-product"><img src="${img(p.id)}" alt=""><div><b>${esc(p.name)}</b><small>${esc(p.category)}</small></div></div></td><td>${money(p.price)}</td><td><span class="${p.stock?'check':'out'}">${p.stock?p.stock+' units':'Out of stock'}</span></td><td><button class="filter-reset" data-action="edit-product" data-id="${p.id}">Edit</button></td></tr>`).join('')}</tbody></table></div>${!list.length?'<p>No products match your filters.</p>':''}</section></div>`,'pricing')}
function calculatePricePreview(data){requireDemoAdmin();const amount=Number(data.amount);if(!Number.isFinite(amount)||amount<=0||amount>1000000||!['percent','fixed'].includes(data.type)||!['increase','decrease'].includes(data.direction)||!data.reason.trim())throw Error('Enter a positive adjustment amount and a reason.');let target;if(data.scope==='all')target=products;else if(data.scope==='category'){if(!pricingCategory)throw Error('Select a category first.');target=products.filter(p=>p.category===pricingCategory)}else if(data.scope==='selected')target=products.filter(p=>pricingSelection.has(p.id));else throw Error('Choose an adjustment scope.');if(!target.length)throw Error('No products selected.');const sign=data.direction==='increase'?1:-1;const rows=target.map(p=>({id:p.id,name:p.name,before:p.price,after:Math.round((p.price+sign*(data.type==='percent'?p.price*amount/100:amount))*100)/100}));if(rows.some(r=>!Number.isFinite(r.after)||r.after<0.01||r.after>1000000))throw Error('This adjustment would create a price outside ₹0.01–₹10,00,000. Reduce the amount.');if(rows.every(r=>r.before===r.after))throw Error('The adjustment is too small to change any prices after rounding.');return {rows,reason:`${data.reason.trim().slice(0,180)} · ${data.direction} ${amount}${data.type==='percent'?'%':' INR'}`,scope:data.scope}}
function showPricePreview(data){pricingPreview=calculatePricePreview(data);showModal(`<div class="eyebrow">Review before applying</div><h2>Update ${pricingPreview.rows.length} product prices?</h2><p>${esc(pricingPreview.reason)}</p><div class="table-scroll bulk-preview-table"><table class="data-table"><thead><tr><th>Product</th><th>Current</th><th>New</th><th>Change</th></tr></thead><tbody>${pricingPreview.rows.map(r=>`<tr><td>${esc(r.name)}</td><td>${money(r.before)}</td><td><b>${money(r.after)}</b></td><td>${r.after>=r.before?'+':''}${money(r.after-r.before)}</td></tr>`).join('')}</tbody></table></div><p>Saved order totals and issued quotes keep their original values. Every price change is recorded in history.</p><div class="import-editor-actions"><button class="btn" data-ops="apply-prices">Apply changes</button><button class="btn btn-outline" data-action="close">Cancel</button></div>`);$('#modal').classList.add('operations-modal')}
function priceHistoryPage(){if(user?.role!=='admin')return admin();return importLayout(`${opsHeading('Catalog audit trail','Price history','Track who changed each price, when it changed and why.','<a class="btn btn-outline" href="#/admin/pricing">Manage pricing</a>')}<section class="panel"><div class="section-head"><h3>${priceHistory.length} recorded changes</h3><button class="btn btn-outline btn-small" data-ops="export-history" ${!priceHistory.length?'disabled':''}>Export CSV</button></div>${priceHistory.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>Product</th><th>Before</th><th>After</th><th>Change</th><th>Reason</th><th>When / by</th></tr></thead><tbody>${priceHistory.map(h=>`<tr><td><b>${esc(h.name)}</b><small>${esc(h.category)}</small></td><td>${money(h.before)}</td><td>${money(h.after)}</td><td>${h.after>=h.before?'+':''}${money(h.after-h.before)}</td><td>${esc(h.reason)}</td><td>${dateLabel(h.at)}<small>${esc(h.actor)}</small></td></tr>`).join('')}</tbody></table></div>`:'<div class="import-empty"><h3>Your changes will appear here.</h3><p>Individual edits, bulk adjustments and published Excel price updates are recorded automatically.</p></div>'}</section>`,'history')}
function downloadCsv(filename,matrix){const protect=v=>{const s=String(v??'');return /^[=+@-]/.test(s)?"'"+s:s};const csv=matrix.map(row=>row.map(v=>'"'+protect(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function prepareCatalogImport(file){requireDemoAdmin();if(importBusy)throw Error('An import is already in progress.');catalogWorkbook=await workbookFromFile(file);catalogFilename=file.name;catalogSheet=catalogWorkbook.SheetNames.find(n=>n.toLowerCase()==='products')||catalogWorkbook.SheetNames[0];if(!catalogSheet)throw Error('The workbook has no worksheets.');resetCatalogMap();showCatalogMapping()}
function resetCatalogMap(){const matrix=sheetMatrix(catalogWorkbook,catalogSheet),headers=(matrix[0]||[]).map(h=>String(h??'').toLowerCase().replace(/[^a-z0-9]/g,''));catalogMap={};for(const [k,aliases] of Object.entries(importAliases))catalogMap[k]=headers.findIndex(h=>aliases.includes(h));catalogPreview=null}
function mappedCatalogMatrix(){const original=sheetMatrix(catalogWorkbook,catalogSheet),keys=Object.keys(importAliases),used=keys.map(k=>Number(catalogMap[k])).filter(v=>v>=0);if(new Set(used).size!==used.length)throw Error('Map each source column to only one field.');if(requiredImportColumns.some(k=>Number(catalogMap[k])<0))throw Error('Map every required field before validation.');return [keys.map(k=>k==='old'?'CompareAtPrice':k==='imageUrl'?'ImageURL':k),...original.slice(1).map(row=>keys.map(k=>Number(catalogMap[k])<0?'':row[Number(catalogMap[k])]??''))]}
function showCatalogMapping(){const matrix=sheetMatrix(catalogWorkbook,catalogSheet),headers=matrix[0]||[];showModal(`<div class="eyebrow">Import preflight · Step 1 of 3</div><h2>Map your spreadsheet.</h2><p>${esc(catalogFilename)} · Choose a worksheet and match its columns to the catalog fields.</p><label class="field">Worksheet<select id="catalogsheet">${catalogWorkbook.SheetNames.map(n=>`<option ${n===catalogSheet?'selected':''}>${esc(n)}</option>`).join('')}</select></label><div class="column-mapping">${Object.keys(importAliases).map(k=>`<label class="field">${esc(k)} ${requiredImportColumns.includes(k)?'<span class="required-label">Required</span>':'<span class="subtle">Optional</span>'}<select data-column-map="${k}"><option value="-1">${requiredImportColumns.includes(k)?'Choose source column':'Not included'}</option>${headers.map((h,i)=>`<option value="${i}" ${Number(catalogMap[k])===i?'selected':''}>${esc(h||'Column '+(i+1))}</option>`).join('')}</select></label>`).join('')}</div><p class="error" id="catalogerror" role="alert"></p><button class="btn" data-ops="catalog-validate">Validate & preview rows</button>`);$('#modal').classList.add('operations-modal')}
function validateCatalogPreview(){requireDemoAdmin();const matrix=mappedCatalogMatrix(),rows=normalizeImportRows(matrix);const drafts=rows.map((r,i)=>({...r,id:'preview-'+i,status:'draft',...(!r.imageUrl?matchImportImage(r.title,r.description):{assetId:null,imageStatus:'checking',imageSource:'URL will be verified during import'})}));catalogPreview={matrix,drafts};const issues=drafts.map(d=>({d,errors:importErrors(d,[...drafts,...importDrafts]).filter(e=>!e.includes('verified product image')&&!e.includes('still being checked'))}));const invalid=issues.filter(x=>x.errors.length).length;showModal(`<div class="eyebrow">Import preflight · Step 2 of 3</div><h2>Review your import.</h2><p>${esc(catalogFilename)} · ${esc(catalogSheet)}</p><div class="preflight-metrics"><div><b>${drafts.length}</b><span>Product rows</span></div><div><b>${drafts.length-invalid}</b><span>Valid details</span></div><div><b>${invalid}</b><span>Need correction</span></div><div><b>${drafts.filter(d=>d.imageStatus==='matched').length}</b><span>Image matches</span></div></div><div class="saved-note">Rows with issues are kept as editable drafts. Image URLs are verified during import. Publication always requires approval.</div><div class="table-scroll bulk-preview-table"><table class="data-table"><thead><tr><th>Row / SKU</th><th>Product</th><th>Price / stock</th><th>Validation</th></tr></thead><tbody>${issues.map(({d,errors})=>`<tr><td>${d.row}<small>${esc(d.sku)}</small></td><td>${esc(d.title)}</td><td>${esc(d.price)} INR<small>${esc(d.stock)} units</small></td><td>${errors.length?`<span class="out">${errors.map(esc).join('<br>')}</span>`:'<span class="check">Details ready</span>'}<small>${d.imageStatus==='matched'?'Reference image matched':d.imageUrl?'Image URL pending verification':'Image required during review'}</small></td></tr>`).join('')}</tbody></table></div><div class="import-editor-actions"><button class="btn" data-ops="catalog-stage">Create ${drafts.length} drafts</button><button class="btn btn-outline" data-ops="catalog-back">Back to mapping</button></div>`);$('#modal').classList.add('operations-modal')}
// Excel republication is included in the same price audit trail.
const originalPublishImportProducts=publishImportProducts;
publishImportProducts=function(ids){const beforeProducts=structuredClone(products),beforeDrafts=structuredClone(importDrafts),beforeHistory=structuredClone(priceHistory),beforeCart=structuredClone(cart);try{const result=originalPublishImportProducts(ids);persistRecords({products,'import-drafts':importDrafts,'price-history':priceHistory});return result}catch(error){products=beforeProducts;importDrafts=beforeDrafts;priceHistory=beforeHistory;cart=beforeCart;try{persistRecords({products,'import-drafts':importDrafts,'price-history':priceHistory,cart})}catch{}throw error}};
document.addEventListener('change',async e=>{try{if(e.target.id==='bulkfile'){await loadBulkFile(e.target.files[0])}if(e.target.dataset.opsFilter==='bulk'){bulkFilter=e.target.value;render()}if(e.target.dataset.opsFilter==='category'){pricingCategory=e.target.value;render()}if(e.target.dataset.opsSelect){const id=Number(e.target.dataset.opsSelect);if(e.target.checked)pricingSelection.add(id);else pricingSelection.delete(id);render()}if(e.target.hasAttribute?.('data-ops-select-all')){for(const p of filteredPricingProducts())if(e.target.checked)pricingSelection.add(p.id);else pricingSelection.delete(p.id);render()}if(e.target.id==='catalogsheet'){catalogSheet=e.target.value;resetCatalogMap();showCatalogMapping()}if(e.target.dataset.columnMap){catalogMap[e.target.dataset.columnMap]=Number(e.target.value);catalogPreview=null}}catch(error){if(e.target.id==='bulkfile'){bulkDraft=null;$('#bulkpreview').innerHTML='';$('#bulkerror').textContent=error.message;$('#bulksubmit').disabled=true}else toast(error.message)}});
document.addEventListener('input',e=>{if(e.target.id==='pricingsearch'){pricingQuery=e.target.value;const pos=e.target.selectionStart;render();$('#pricingsearch').focus();$('#pricingsearch').setSelectionRange(pos,pos)}});
document.addEventListener('submit',e=>{const f=e.target;if(!['bulkrequestform','bulkmanageform','priceadjustform','stocksetform'].includes(f.id))return;e.preventDefault();const data=Object.fromEntries(new FormData(f));try{if(f.id==='bulkrequestform'){submitBulkRequest(data);render();toast('Bulk quotation request submitted')}else if(f.id==='bulkmanageform'){updateBulkOrder(f.dataset.id,data);closeModal();render();toast('Request updated')}else if(f.id==='priceadjustform')showPricePreview(data);else{commitProductChanges([...pricingSelection].map(id=>({id,stock:Number(data.stock)})),'Stock quantity update');closeModal();render();toast('Stock quantities updated')}}catch(error){const target=f.querySelector('[role="alert"]');if(target)target.textContent=error.message;else toast(error.message)}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-ops]');if(!b)return;const action=b.dataset.ops;try{if(action==='bulk-detail'){bulkDetail(b.dataset.id);return}requireDemoAdmin();if(action==='apply-prices'){if(!pricingPreview)throw Error('Preview your price adjustment first.');if(pricingPreview.rows.some(r=>product(r.id)?.price!==r.before))throw Error('Prices have changed. Generate a new preview.');commitProductChanges(pricingPreview.rows.map(r=>({id:r.id,price:r.after})),pricingPreview.reason);pricingPreview=null;closeModal();render();toast('Prices updated and recorded in history')}else if(action==='stock-zero'||action==='stock-set'){if(!pricingSelection.size)throw Error('Select products first.');showModal(`<div class="eyebrow">Inventory update</div><h2>${action==='stock-zero'?'Mark selected items out of stock?':'Set selected stock quantity'}</h2><p>This updates ${pricingSelection.size} selected products. Cart quantities will be adjusted to available stock.</p><form id="stocksetform"><label class="field">Available units<input name="stock" type="number" min="0" max="100000" step="1" value="${action==='stock-zero'?0:1}" ${action==='stock-zero'?'readonly':''} required></label><p class="error" role="alert"></p><button class="btn">Confirm inventory update</button></form>`)}else if(action==='export-history')downloadCsv('power-electronics-price-history.csv',[['Product','Category','Before INR','After INR','Reason','Timestamp','Admin'],...priceHistory.map(h=>[h.name,h.category,h.before,h.after,h.reason,h.at,h.actor])]);else if(action==='export-issues')downloadCsv('power-electronics-import-issues.csv',[['File','Row','SKU','Title','Issues'],...filteredDrafts().filter(d=>importErrors(d).length).map(d=>[importBatches.find(b=>b.id===d.batchId)?.filename,d.row,d.sku,d.title,importErrors(d).join('; ')])]);else if(action==='catalog-validate')validateCatalogPreview();else if(action==='catalog-back')showCatalogMapping();else if(action==='catalog-stage'){if(!catalogPreview)throw Error('Validate the spreadsheet first.');const matrix=catalogPreview.matrix,filename=catalogFilename;catalogPreview=null;closeModal();await stageImport(matrix,filename)}}catch(error){const target=$('#catalogerror');if(target)target.textContent=error.message;else toast(error.message)}});
$('#modal').addEventListener('close',()=>{$('#modal').classList.remove('operations-modal');pricingPreview=null});
